'use strict';
Object.assign(V2_GLYPHS,{chat:'<path d="M21 11.5a8.38 8.38 0 01-.9 3.8 8.5 8.5 0 01-7.6 4.7 8.38 8.38 0 01-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 01-.9-3.8 8.5 8.5 0 014.7-7.6 8.38 8.38 0 013.8-.9h.5a8.48 8.48 0 018 8v.5z"></path>',idea:'<path d="M12 2a7 7 0 015 11.9V16a2 2 0 01-2 2h-6a2 2 0 01-2-2v-2.1A7 7 0 0112 2zm-2 18h4m-2 0v2"></path>',bolt:'<path d="M13 2L4 13h6l-1 9 9-11h-6l1-9z"></path>',chart:'<path d="M18 20V10M12 20V4M6 20v-6"></path>',tree:'<path d="M12 22V8m0 0l-4 4m4-4l4 4M8 2l4 6 4-6"></path>'});
function v2DialogClose(cls,popup){return '<button type="button" class="'+cls+'"'+actAttrs('close',{popup:popup||'dialog'})+' aria-label="'+h(tc('common.close'))+'">'+v2Glyph('close','h-4 w-4')+'</button>';}
function v2DialogError(error,cls){return error?'<div role="alert" class="'+cls+'">'+h(error)+'</div>':'';}
function v2DialogCancel(cls,popup){return '<button type="button" class="'+cls+'"'+actAttrs('close',{popup:popup||'dialog'})+'>'+h(tc('common.cancel'))+'</button>';}
function v2DialogSubmit(d,cls){return '<button type="submit" class="'+cls+'"'+(d.busy?' disabled':'')+'>'+h(d.busy?(d.busyLabel||tc('v2h.dialog.processing')):d.ok)+'</button>';}
function v2DialogInput(f,cls){
 const attrs=' id="'+h(f.id)+'"'+(f.req?' required':'')+(f.disabled?' disabled':'')+(f.readonly?' readonly':'')+(f.placeholder?' placeholder="'+h(f.placeholder)+'"':'')+(f.max?' maxlength="'+f.max+'"':'')+(f.change?' data-change="'+h(f.change)+'"':'');
 if(f.options)return '<select class="'+cls+'"'+attrs+'>'+f.options.map(function(o){if(typeof o==='string')o={v:o,label:o};return '<option value="'+h(o.v)+'"'+(String(o.v)===String(f.value)?' selected':'')+'>'+h(o.label||o.title)+'</option>';}).join('')+'</select>';
 if(f.area)return '<textarea class="'+cls+'"'+attrs+' rows="'+(f.rows||4)+'">'+h(f.value)+'</textarea>';
 return '<input type="'+(f.type||'text')+'" class="'+cls+'"'+attrs+' value="'+h(f.value)+'"'+(f.min!=null?' min="'+f.min+'"':'')+(f.maxv!=null?' max="'+f.maxv+'"':'')+'>';
}
/* mission-control/ImportProjectModal.tsx */
PDL_COMPONENTS.v2ImportProjectDialog=function(p,sc,root){
 const d=pv(p.data,sc,root),cls='mt-1 w-full rounded-[10px] border-transparent bg-[var(--console-field-bg,var(--console-card-bg))] px-3 py-2 text-sm text-cafe focus:outline-none focus:ring-1 focus:ring-cafe-accent';
 return '<form data-form="dialog" role="dialog" aria-modal="true" class="w-full max-w-md rounded-xl bg-[var(--console-card-bg)] p-6 shadow-lg"><h2 class="mb-4 text-base font-bold text-cafe">'+h(d.title)+'</h2><div class="space-y-3">'+d.fields.map(function(f){return '<label class="block"><span class="text-xs font-medium text-cafe-secondary">'+h(f.label)+(f.req?' *':'')+'</span>'+v2DialogInput(f,cls)+'</label>';}).join('')+'</div>'+v2DialogError(d.error,'mt-3 rounded-lg border border-conn-red-ring bg-conn-red-bg px-3 py-2 text-xs text-conn-red-text')+'<div class="mt-4 flex justify-end gap-2">'+v2DialogCancel('rounded-lg bg-[var(--console-shell-bg)] px-4 py-1.5 text-xs font-medium text-cafe-secondary hover:bg-[var(--console-hover-bg)]')+v2DialogSubmit(Object.assign({},d,{busyLabel:tc('v2h.dialog.importing')}),'rounded-lg bg-[var(--mc-accent)] px-4 py-1.5 text-xs font-medium text-[var(--cafe-surface)] hover:bg-[var(--mc-accent-hover)] disabled:opacity-40')+'</div></form>';
};
PDL_COMPONENTS.v2ImportProjectDialog.dialog=true;
/* ForceResetDialog.tsx */
function v2ForceResetIcon(kind){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" class="w-[17px] h-[17px] flex-shrink-0 mt-0.5"><circle cx="12" cy="12" r="10"></circle>'+({ban:'<path d="m4.9 4.9 14.2 14.2"></path>',check:'<path d="m9 12 2 2 4-4"></path>',info:'<path d="M12 16v-4"></path><path d="M12 8h.01"></path>'}[kind])+'</svg>';}
PDL_COMPONENTS.v2ForceResetDialog=function(p,sc,root){const d=pv(p.data,sc,root);return '<form data-form="dialog" role="dialog" aria-modal="true" class="w-full max-w-sm rounded-2xl overflow-hidden bg-cafe-surface-elevated shadow-xl"><div class="flex items-center justify-between px-5 py-4 border-b border-cafe"><h3 class="text-sm font-bold" style="color:var(--cafe-text)">'+h(tc('v2h.dialog.forceTitle'))+'</h3>'+v2DialogClose('text-cafe-muted hover:text-cafe-secondary transition-colors')+'</div><div class="px-5 py-4 flex flex-col gap-3" style="color:var(--cafe-text)">'+[['critical','ban','forceDoes','forceDoesText'],['success','check','forceKeeps','forceKeepsText'],['info','info','forceWhen','forceWhenText']].map(function(x){return '<div class="flex gap-2.5 items-start text-sm"><span style="color:var(--semantic-'+x[0]+')">'+v2ForceResetIcon(x[1])+'</span><span><b class="font-semibold">'+h(tc('v2h.dialog.'+x[2]))+'</b>'+h(tc('v2h.dialog.'+x[3]))+'</span></div>';}).join('')+v2DialogError(d.error,'text-sm text-conn-red-text')+'</div><div class="flex justify-end gap-2.5 px-5 py-3.5 border-t border-cafe">'+v2DialogCancel('rounded-xl px-4 py-2 text-sm font-semibold border border-cafe bg-cafe-surface-elevated')+'<button type="submit" class="rounded-xl px-4 py-2 text-sm font-semibold text-white transition-opacity disabled:opacity-60" style="background-color:var(--semantic-critical)"'+(d.busy?' disabled':'')+'>'+h(d.ok)+'</button>'+'</div></form>';};
PDL_COMPONENTS.v2ForceResetDialog.dialog=true;
/* UnifiedAuthModal.tsx and its AccountConnectionFields. */
PDL_COMPONENTS.v2UnifiedAuthDialog=function(p,sc,root){const d=pv(p.data,sc,root),cls='mt-1 w-full rounded-lg border border-[var(--console-border-soft)] bg-[var(--console-field-bg)] px-3 py-2 text-sm text-cafe-primary outline-none focus:ring-1 focus:ring-cafe-accent';return '<form data-form="dialog" role="dialog" aria-modal="true" class="w-full max-w-md rounded-2xl border border-[var(--console-border-soft)] bg-[var(--console-card-bg)] p-5 shadow-2xl"><div class="mb-1 flex items-center justify-between"><h3 class="font-semibold text-cafe-primary">'+h(d.title)+'</h3>'+v2DialogClose('rounded-full p-1 text-cafe-muted hover:bg-[var(--console-hover-bg)] hover:text-cafe-secondary')+'</div><div class="mb-4 flex rounded-lg border border-[var(--console-border-soft)] p-0.5'+(d.panes.locked?' opacity-50':'')+'">'+d.panes.items.map(function(x){return '<button type="button" class="flex-1 rounded-md px-3 py-1.5 text-sm font-medium transition '+(x.v===d.panes.cur?'bg-[var(--console-active-bg)] text-cafe-primary':'text-cafe-muted')+'"'+actAttrs('set',{path:'s.dialog.panes.cur',v:x.v})+(d.panes.locked?' disabled':'')+'>'+h(x.label)+'</button>';}).join('')+'</div><div class="space-y-3">'+d.fields.filter(function(f){return f.pane===d.panes.cur;}).map(function(f){if(f.chips||f.env)return dlgField(f);return '<label class="block text-sm text-cafe-secondary">'+h(f.label)+v2DialogInput(f,cls)+(f.help?'<p class="mt-1 text-sm text-cafe-muted">'+h(f.help)+'</p>':'')+'</label>';}).join('')+'</div>'+v2DialogError(d.error,'mt-3 text-xs text-semantic-critical')+'<div class="mt-4 flex justify-end">'+v2DialogSubmit(d,'rounded-lg bg-cafe-accent px-5 py-2 text-sm font-semibold text-[var(--cafe-surface)] transition hover:bg-cafe-accent-hover disabled:opacity-50')+'</div></form>';};
