PDL_COMPONENTS.v2ThreadSettingsPanel=function(p,sc,root){const d=pv(p.data,sc,root),x=d.data;return '<aside id="thread-settings-'+h(x.id)+'" role="dialog" aria-modal="false" aria-labelledby="thread-settings-title-'+h(x.id)+'" data-thread-settings-panel="true" data-testid="thread-settings-panel" class="thread-settings-popover" style="top:60px;right:8px;max-height:calc(100vh - 68px)"><header class="flex flex-shrink-0 items-start gap-3 border-b border-cafe-subtle px-4 py-3.5"><div class="min-w-0 flex-1"><h2 id="thread-settings-title-'+h(x.id)+'" class="text-sm font-semibold text-cafe-black">'+h(tc('v2h.threadSettings.title'))+'</h2><p class="mt-0.5 truncate text-micro text-cafe-muted" title="'+h(x.name)+'">'+h(x.name)+'</p></div><button type="button" aria-label="'+h(tc('v2h.threadSettings.close'))+'"'+actAttrs('close',{popup:'chat.modal'})+' class="rounded-lg p-1 text-cafe-muted transition-colors hover:bg-cafe-surface-elevated hover:text-cafe-secondary">'+v2Glyph('close','h-4 w-4')+'</button></header><div class="min-h-0 flex-1 overflow-y-auto p-2">'+v2DialogError(d.error,'px-3 text-xs text-conn-red-text')+pvBlocks([{type:'view',id:d.view,data:{lit:d.data}}],sc,root)+'</div></aside>';};
PDL_COMPONENTS.v2ThreadSettingsContent=function(p,sc,root){const x=pv(p.data,sc,root);return '<div class="thread-background-settings"><label class="thread-background-menu-row"><span>'+h(tc(x.pinned?'v2h.threadSettings.pinned':'v2h.threadSettings.pin'))+'</span><input type="checkbox"'+(x.pinned?' checked':'')+actAttrs('setStatus',{entity:'pin',id:x.id})+'></label><button type="button" class="thread-background-menu-row shell-focusable" data-testid="thread-background-entry" disabled data-tip="'+h(tc('v2h.threadSettings.backgroundUnavailable'))+'"><span>'+h(tc('v2h.threadSettings.background'))+'</span><span class="flex min-w-0 items-center gap-2 text-xs" style="color:var(--shell-muted)"><span aria-hidden="true">›</span></span></button></div>'+(x.path&&x.path!=='default'?'<div data-testid="thread-project-path" class="mb-2 rounded-xl border border-cafe-subtle px-3 py-2"><p class="text-micro text-cafe-muted">'+h(tc('threadSettings.project'))+'</p><p class="mt-1 break-all text-xs text-cafe-secondary">'+h(x.path)+'</p></div>':'')+(p.groups||[]).map(function(g){return '<div data-settings-group="'+h(g.id)+'" class="mb-3 last:mb-0"><h3 class="px-3 py-2 text-micro font-semibold text-cafe-muted">'+pvText(g.title,sc,root)+'</h3>'+g.sections.map(function(s){const open=!!pv(s.open,sc,root);return '<section class="mb-1 overflow-hidden rounded-xl border border-cafe-subtle last:mb-0"><button type="button" aria-expanded="'+open+'" aria-controls="thread-settings-section-'+h(s.id)+'" '+actAttrs(s.toggle.act,s.toggle.args)+' data-v2-thread-section class="flex w-full items-center gap-3 px-3 py-3 text-left transition-colors hover:bg-cafe-surface-elevated"><span class="flex h-8 w-8 flex-shrink-0 items-center justify-center rounded-lg bg-cafe-surface-elevated text-cafe-accent">'+v2Glyph(s.icon,'h-4 w-4')+'</span><span class="min-w-0 flex-1"><span class="block text-xs font-semibold text-cafe-black">'+pvText(s.title,sc,root)+'</span><span class="mt-0.5 block text-micro text-cafe-muted">'+pvText(s.description,sc,root)+'</span></span><svg data-v2-thread-chevron class="h-4 w-4 flex-shrink-0 text-cafe-muted transition-transform'+(open?' rotate-180':'')+'" viewBox="0 0 20 20" fill="currentColor" aria-hidden="true"><path fill-rule="evenodd" d="M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z" clip-rule="evenodd"></path></svg></button><div id="thread-settings-section-'+h(s.id)+'"'+(open?'':' hidden')+' class="border-t border-cafe-subtle bg-cafe-bg/40" data-v2-thread-section-body>'+pvBlocks(s.blocks,sc,root)+'</div></section>';}).join('')+'</div>';}).join('')+pvBlocks(p.extra,sc,root);};
