PDL_COMPONENTS.v2PluginMarketplaceDialog=function(p,sc,root){const x=pv(p.data,sc,root),close=pvDeep(p.close,root,sc),sources=x.load==='error'?[]:x.raw.sources,failures=sources.filter(function(s){return s.status==='error';}).length;return '<div class="fixed inset-0 z-[100] flex items-center justify-center bg-[var(--console-overlay-backdrop)] p-4 backdrop-blur-sm"><section role="dialog" aria-modal="true" aria-labelledby="plugin-marketplaces-title" class="flex max-h-[calc(100dvh-32px)] w-full max-w-xl flex-col overflow-hidden rounded-2xl bg-[var(--console-card-bg)] shadow-lg"><div class="shrink-0 p-4"><div class="flex items-center justify-between"><h2 id="plugin-marketplaces-title" class="text-lg font-semibold text-cafe">'+h(tc('v2h.marketplaces.title'))+'</h2><button type="button" aria-label="'+h(tc('v2h.marketplaces.close'))+'" class="flex h-[26px] w-[26px] items-center justify-center rounded-lg text-cafe-muted transition-colors hover:bg-[var(--console-hover-bg)] hover:text-cafe-accent"'+actAttrs(close.act,close.args)+'>'+v2HubGlyph('x','h-4 w-4')+'</button></div></div><div class="min-h-0 flex-1 space-y-4 overflow-y-auto p-4 pt-0"><ul class="divide-y divide-[var(--console-border-soft)]">'+sources.map(function(s){return '<li class="space-y-2 py-3"><div class="flex items-center gap-2"><span class="min-w-0 flex-1 truncate font-medium text-cafe">'+h(s.origin==='official'?tc('v2h.marketplaces.official'):s.url.replace(/\.git$/,'').split(/[/:]/).at(-1))+'</span>'+(s.origin!=='user'?'<span class="text-xs text-cafe-muted">'+h(tc(s.origin==='official'?'v2h.marketplaces.default':'v2h.marketplaces.environment'))+'</span>':'<button type="button" class="flex h-[26px] w-[26px] items-center justify-center rounded-lg text-cafe-muted transition-colors hover:bg-[var(--console-hover-bg)] hover:text-cafe-accent" aria-label="'+h(tc('v2h.marketplaces.removeSource',s.url,s.branch||tc('v2h.marketplaces.defaultBranch')))+'"'+actAttrs('remove',{entity:'marketSource',id:s.id})+'>'+v2HubGlyph('trash','h-4 w-4')+'</button>')+'</div><p title="'+h(s.url)+'" class="truncate font-mono text-xs text-cafe-muted">'+h(s.url.replace(/^(https?|ssh):\/\//,'').replace(/\.git$/,''))+'</p><p class="text-xs text-cafe-secondary">'+h(tc('v2h.marketplaces.branch',s.branch||tc('v2h.marketplaces.defaultBranch')))+'</p><p class="text-xs text-cafe-secondary">'+h(s.status==='ready'?tc('v2h.marketplaces.synced',s.pluginCount):s.status==='error'?s.error:tc('v2h.marketplaces.pending'))+'</p></li>';}).join('')+'</ul><form class="ifield space-y-2" data-go="marketSourceAdd" data-for="market-url"><label for="market-url" class="text-sm font-medium text-cafe">'+h(tc('v2h.marketplaces.addSource'))+'</label><div class="flex flex-col gap-2 sm:flex-row"><input id="market-url" class="input w-full min-w-0 flex-1 rounded-lg bg-[var(--console-input-bg)] px-3 py-2 text-sm text-cafe outline-none" aria-label="'+h(tc('v2h.marketplaces.sourceUrl'))+'" placeholder="'+h(tc('v2h.marketplaces.urlPlaceholder'))+'" data-on-enter="fieldGo" data-v2-market-url><input id="market-branch" aria-label="'+h(tc('v2h.marketplaces.branchName'))+'" placeholder="'+h(tc('v2h.marketplaces.branchPlaceholder'))+'" class="w-full min-w-0 flex-1 rounded-lg bg-[var(--console-input-bg)] px-3 py-2 text-sm text-cafe outline-none" data-on-enter="fieldGo"><button type="button" data-v2-market-add disabled class="shrink-0 rounded-full bg-cafe-accent px-4 py-1.5 text-xs font-semibold text-[var(--cafe-accent-foreground)] hover:bg-cafe-accent-hover disabled:cursor-not-allowed disabled:opacity-50 transition"'+actAttrs('fieldGo',{})+'>'+h(tc('common.add'))+'</button></div></form>'+v2DialogError(x.raw.error,'text-sm text-conn-red-text')+'</div><div class="flex shrink-0 justify-end gap-2 border-t border-[var(--console-border-soft)] p-4">'+(failures||x.load==='error'?'<button type="button" class="'+V2_MARKET_SECONDARY+'"'+actAttrs('marketSourcesRefresh',{})+'>'+h(tc('v2h.marketplaces.retry'))+'</button>':'')+'<button type="button" class="'+V2_MARKET_SECONDARY+'"'+actAttrs(close.act,close.args)+'>'+h(tc('common.done'))+'</button></div></section></div>';};
